package br.com.archlab.simulation.core.v3;
import org.junit.jupiter.api.Test;import java.util.*;import static org.junit.jupiter.api.Assertions.*;import static br.com.archlab.simulation.core.v3.SynchronousExecutionV3Test.*;import static br.com.archlab.simulation.core.v3.AsynchronousExecutionV3Test.reference;import static br.com.archlab.simulation.core.v3.AsynchronousExecutionV3Test.inject;
class OutcomeAndQueueRecoveryV3Test {
    @Test void terminalStepResultsRetainSuccessAndErrorPayloadProfile(){for(boolean available:List.of(true,false)){var engine=new SimulationEngineV3(fixture(null,null,false,available));engine.run();var profile=available?id("ok"):id("error");assertTrue(engine.checkpoint().current().state().entities().values().stream().anyMatch(e->e instanceof RuntimeEntityV3.StepResult result && profile.equals(result.profileId())));}}
    @Test void availableQueueWakesReadyMessagesAfterAnOutage(){var r=reference(ExecutionPlanV3.AwaitPublish.NONE,Map.of());var s=r.scenario();var request=new SimulationRequestV3(r.architecture(),new SimulationRequestV3.Scenario(s.id(),s.entry(),List.of(new InitialStateV3.Queue(id("messages"),2L)),s.parameters()),r.options());var engine=inject(new SimulationEngineV3(request),150,DeterministicSchedulerV3.Phase.ENVIRONMENT_CHANGE,new SimulationEventV3.ResourceStateChangeDue(id("messages"),id("outage-queue"),id("UNAVAILABLE")));engine=inject(engine,200,DeterministicSchedulerV3.Phase.ENVIRONMENT_CHANGE,new SimulationEventV3.ResourceStateChangeDue(id("messages"),id("recover-queue"),id("AVAILABLE")));engine.run();assertEquals(120L,engine.control().principalResponseAt());assertEquals(290,engine.checkpoint().current().agenda().nowMs());assertEquals("COMPLETED",engine.control().globalStop());assertTrue(engine.checkpoint().current().state().entities().values().stream().anyMatch(e->e instanceof RuntimeEntityV3.QueueEntry q && q.status()==RuntimeEntityV3.QueueEntryStatus.ACKNOWLEDGED));}
}
